  h.textContent.trim().toLowerCase().includes('see also')
);

if (seeAlsoHeading) {
  // Get the next sibling elements until we hit another heading
  let element = seeAlsoHeading.nextElementSibling;
  const links = [];

  while (element && !element.matches('h2, h3')) {
    if (element.tagName === 'UL' || element.tagName === 'DIV') {
      const listItems = element.querySelectorAll('li');
      listItems.forEach(li => {
        const link = li.querySelector('a');
        if (link) {
          links.push(link.textContent.trim());
        }
      });
    }
    element = element.nextElementSibling;
  }

  if (links.length > 0) {
    console.log("Total links in See also:", links.length);
    console.log("Last link:", links[links.length - 1]);
    links[links.length - 1];
  } else {
    "No links found";
  }
} else {
  "See also heading not found";
}
'''

