# Check for pagination and get all books from all pages
js("""(() => {
  const results = [];

  // Function to extract books from current page
  function extractBooks() {
    const books = document.querySelectorAll('.product_pod');
    books.forEach(book => {
      const title = book.querySelector('h3 a')?.getAttribute('title') || 'N/A';
      const priceText = book.querySelector('.price_color')?.textContent?.trim() || 'N/A';
      // Extract numeric price
      const priceMatch = priceText.match(/£([\\d.]+)/);
      const price = priceMatch ? parseFloat(priceMatch[1]) : null;
      results.push({title, priceText, price});
    });
  }

  // Extract from first page
  extractBooks();

  // Check for next page link
  let nextPage = document.querySelector('li.next a');
  while (nextPage) {
    const href = nextPage.getAttribute('href');
    if (!href) break;

    // Navigate to next page
    window.location.href = href;

    // Wait for page load (simple wait)
    const start = Date.now();
    while (Date.now() - start < 2000) {}

    extractBooks();
    nextPage = document.querySelector('li.next a');
  }

  return results;
})()""")

